
:global(*) {
  box-sizing: border-box;
}

/* 暮紫深色渐变背景 */
:global(body) {
  margin: 0;
  min-width: 0;
  background: #241a28;
  color: #f5ece8;
  font-family: 'Noto Sans SC', 'PingFang SC', 'Microsoft YaHei', system-ui, sans-serif;
}

:global(button),
:global(input) {
  font: inherit;
}

:global(button) {
  cursor: pointer;
}

/* ── 介绍页：游戏标题画面感 ───────────────────────────────────────── */

.intro-shell {
  --nt-bg: linear-gradient(180deg, #241a28, #1c151f);
  --nt-panel: rgba(42, 34, 56, 0.85);
  --nt-ink: #f5ece8;
  --nt-ink-soft: #d4bec8;
  --nt-ink-faint: #9a8492;
  --nt-line: rgba(245, 236, 232, 0.12);
  --nt-rule: rgba(245, 236, 232, 0.07);
  --nt-accent: #e8a0b8;
  --nt-fill: linear-gradient(135deg, #e8a0b8, #c9708a);
  --nt-fill-solid: #c9708a;
  --nt-ok: #7baa92;
  --nt-err: #e8a0b8;
  --nt-soft: 0 2px 12px rgba(0, 0, 0, 0.18);
  --nt-soft-sm: 0 1px 6px rgba(0, 0, 0, 0.14);
  --nt-sans: 'Noto Sans SC', 'PingFang SC', 'Microsoft YaHei', system-ui, sans-serif;

  position: relative;
  isolation: isolate;
  counter-reset: block;
  display: flex;
  flex-direction: column;
  gap: 0;
  width: min(100%, 780px);
  min-height: 100vh;
  margin: 0 auto;
  padding: 38px 24px 26px;
  background: var(--nt-bg);
  color: var(--nt-ink);
  font-family: var(--nt-sans);
}

/* 极淡花影装饰 */
.intro-shell::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background:
    radial-gradient(ellipse 60% 40% at 20% 10%, rgba(184, 154, 212, 0.06) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 80% 90%, rgba(232, 160, 184, 0.05) 0%, transparent 70%);
}

@media (prefers-color-scheme: light) {
  :global(body) {
    background: #faf5f2;
    color: #3d2d33;
  }

  .intro-shell {
    --nt-bg: linear-gradient(180deg, #faf5f2, #f3ebe8);
    --nt-panel: rgba(255, 250, 248, 0.92);
    --nt-ink: #3d2d33;
    --nt-ink-soft: #5c4450;
    --nt-ink-faint: #8c6e78;
    --nt-line: rgba(61, 45, 51, 0.12);
    --nt-rule: rgba(61, 45, 51, 0.07);
    --nt-accent: #c9708a;
    --nt-fill: linear-gradient(135deg, #e8a0b8, #c9708a);
    --nt-fill-solid: #c9708a;
    --nt-ok: #6b8a6f;
    --nt-err: #c9708a;
    --nt-soft: 0 2px 12px rgba(61, 45, 51, 0.10);
    --nt-soft-sm: 0 1px 6px rgba(61, 45, 51, 0.08);
  }
}

.intro-header {
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: 0 0 16px;
  border-bottom: 2px solid var(--nt-ink);
}

.eyebrow {
  margin: 0 0 14px;
  color: var(--nt-accent);
  font-family: var(--nt-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.18em;
  line-height: 1.4;
  text-transform: uppercase;
}

.cover-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 18px;
  min-width: 0;
}

h1 {
  margin: 0;
  color: var(--nt-ink);
  font-family: var(--nt-sans);
  font-size: clamp(40px, 9vw, 56px);
  font-weight: 900;
  line-height: 0.96;
  letter-spacing: -0.045em;
}

/* 期号：猩红细线 + 编号 + 卷名 */
.issue-mark {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  flex: 0 0 auto;
  padding-left: 12px;
  border-left: 1px solid var(--nt-line);
  font-family: var(--nt-mono);
  line-height: 1.1;
}

.issue-mark b {
  color: var(--nt-accent);
  font-size: 20px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.issue-mark i {
  color: var(--nt-ink-faint);
  font-size: 9px;
  font-style: normal;
  letter-spacing: 0.18em;
}

.subtitle {
  margin: 14px 0 0;
  max-width: 46ch;
  color: var(--nt-ink-faint);
  font-size: 12.5px;
  line-height: 1.75;
}

.cover-rule {
  width: 72px;
  height: 2px;
  margin-top: 16px;
  background: var(--nt-accent);
}

.world-note {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 12px;
  color: var(--nt-ink-faint);
  font-family: var(--nt-mono);
  font-size: 9.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  white-space: nowrap;
}

.note-dot {
  width: 6px;
  height: 6px;
  background: var(--nt-accent);
}

/* ── 栏目 ───────────────────────────────────────────────────────────── */

.intro-block {
  counter-increment: block;
  padding: 18px 0 16px;
  border-bottom: 1px solid var(--nt-rule);
}

.block-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--nt-line);
}

.block-head h3 {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin: 0;
  color: var(--nt-ink);
  font-size: 15px;
  font-weight: 800;
  letter-spacing: -0.01em;

  &::before {
    content: '0' counter(block);
    color: var(--nt-accent);
    font-family: var(--nt-mono);
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 0;
  }
}

.block-hint {
  margin: 12px 0 0;
  color: var(--nt-ink-faint);
  font-size: 10.5px;
  line-height: 1.8;
}

.mini-button {
  padding: 4px 10px;
  border: 1px solid var(--nt-line);
  border-radius: 0;
  background: transparent;
  color: var(--nt-ink-soft);
  font-family: var(--nt-mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition:
    color 0.12s linear,
    border-color 0.12s linear,
    background 0.12s linear,
    transform 0.08s linear;
}

.mini-button:hover {
  border-color: var(--nt-accent);
  background: var(--nt-accent);
  color: var(--nt-bg);
}

.mini-button:focus-visible {
  border-color: var(--nt-accent);
  outline: 2px solid var(--nt-accent);
  outline-offset: 2px;
}

.mini-button:active {
  transform: translateY(1px);
}

/* ── 环境检测：两行数据表 ───────────────────────────────────────────── */

.check-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.check-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 0;
  border: 0;
  border-bottom: 1px solid var(--nt-rule);
  border-radius: 0;
  background: transparent;
  transition: background 0.16s linear;
}

.check-light {
  position: relative;
  flex: 0 0 8px;
  width: 8px;
  height: 8px;
  border-radius: 0;
  transition: background 0.16s linear;
}

.check-copy {
  display: flex;
  flex: 1 1 auto;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}

.check-copy strong {
  color: var(--nt-ink);
  font-size: 12.5px;
  font-weight: 700;
}

.check-copy strong em {
  margin-left: 7px;
  color: var(--nt-ink-faint);
  font-family: var(--nt-mono);
  font-size: 9px;
  font-style: normal;
  letter-spacing: 0.1em;
}

.check-copy small {
  color: var(--nt-ink-faint);
  font-size: 10.5px;
  line-height: 1.55;
}

.check-verdict {
  flex: 0 0 auto;
  font-family: var(--nt-mono);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.check-card.is-ok .check-light {
  background: var(--nt-ok);
}

.check-card.is-ok .check-verdict {
  color: var(--nt-ok);
}

.check-card.is-missing .check-light {
  background: var(--nt-accent);
}

.check-card.is-missing .check-verdict {
  color: var(--nt-accent);
}

/* ── 链接卡：反色 hover ─────────────────────────────────────────────── */

.link-grid {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.link-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 13px;
  border: 1px solid var(--nt-line);
  border-radius: 0;
  background: transparent;
  color: inherit;
  text-decoration: none;
  transition:
    transform 0.08s linear,
    border-color 0.12s linear,
    background 0.12s linear;
}

.link-card:hover {
  border-color: var(--nt-accent);
  background: var(--nt-accent);
  color: var(--nt-bg);
}

.link-card:focus-visible {
  border-color: var(--nt-accent);
  outline: 2px solid var(--nt-accent);
  outline-offset: 2px;
}

.link-card:active {
  transform: translateY(1px);
}

.link-card:hover .link-glyph {
  /* hover stays flower gradient; no override needed */
}

.link-copy {
  display: flex;
  flex: 1 1 auto;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}

.link-copy strong {
  color: inherit;
  font-size: 12.5px;
  font-weight: 700;
}

.link-copy small {
  color: var(--nt-ink-faint);
  font-size: 10.5px;
  line-height: 1.5;
}

.link-arrow {
  color: var(--nt-accent);
  font-size: 13px;
}

/* ── 目录 ───────────────────────────────────────────────────────────── */

.guide-list {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
  counter-reset: guide;
}

.guide-list li {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 1px solid var(--nt-rule);
  color: var(--nt-ink);
  font-size: 12px;
  line-height: 1.65;
}

.guide-list li::before {
  flex: 0 0 22px;
  color: var(--nt-accent);
  font-size: 12px;
  font-weight: 700;
  content: counter(guide, decimal-leading-zero);
  counter-increment: guide;
}

.guide-list b {
  flex: 0 0 auto;
  font-weight: 700;
  white-space: nowrap;
}

.guide-list span {
  flex: 1 1 auto;
  min-width: 0;
  color: var(--nt-ink-faint);
  font-size: 11.5px;
}

/* ── 清理 ───────────────────────────────────────────────────────────── */

.cleanup-note {
  margin: 0 0 12px;
  color: var(--nt-ink-faint);
  font-size: 11px;
  line-height: 1.85;
}

.cleanup-button {
  padding: 10px 18px;
  border: 1.5px solid var(--nt-line);
  border-radius: 999px;
  background: transparent;
  color: var(--nt-ink);
  font-size: 10.5px;
  font-weight: 500;
  transition:
    background 0.18s ease,
    color 0.18s ease,
    border-color 0.18s ease,
    transform 0.12s ease;
}

.cleanup-button:hover:not(:disabled) {
  border-color: var(--nt-accent);
  background: var(--nt-accent);
  color: #fff;
}

.cleanup-button:focus-visible:not(:disabled) {
  border-color: var(--nt-accent);
  outline: 2px solid var(--nt-accent);
  outline-offset: 2px;
}

.cleanup-button:active:not(:disabled) {
  transform: scale(0.97);
}

.cleanup-button:disabled {
  cursor: wait;
  opacity: 0.6;
}

.cleanup-button.is-confirm {
  border-color: transparent;
  background: var(--nt-fill);
  color: #ffffff;
  font-weight: 600;
}

.cleanup-button.is-done {
  border-color: var(--nt-ok);
  color: var(--nt-ok);
  background: transparent;
}

.cleanup-status {
  margin: 10px 0 0;
  color: var(--nt-ink-faint);
  font-size: 10.5px;
  line-height: 1.8;
}

/* ── 进入按钮：花色渐变大圆角，白字，hover 稍亮，柔光 ─────────────── */

.primary-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-width: 126px;
  min-height: 44px;
  padding: 12px 22px;
  border: none;
  border-radius: 999px;
  background: var(--nt-fill);
  color: #ffffff;
  font-family: var(--nt-sans);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.02em;
  box-shadow: 0 4px 16px rgba(232, 160, 184, 0.32);
  transition:
    transform 0.18s cubic-bezier(0.34, 1.2, 0.64, 1),
    filter 0.18s ease,
    box-shadow 0.18s ease,
    opacity 0.15s ease;
}

.primary-button:hover:not(:disabled) {
  filter: brightness(1.08);
  box-shadow: 0 8px 24px rgba(232, 160, 184, 0.40);
}

.primary-button:focus-visible:not(:disabled) {
  outline: 2px solid var(--nt-accent);
  outline-offset: 3px;
}

.primary-button:active:not(:disabled) {
  transform: translateY(1px);
  box-shadow: 0 2px 8px rgba(232, 160, 184, 0.16);
}

.primary-button:disabled {
  cursor: wait;
  opacity: 0.6;
  box-shadow: none;
}

.button-arrow {
  font-size: 15px;
}

.intro-start {
  margin: 20px auto 0;
  width: min(100%, 360px);
}

.swipe-hint {
  margin: 12px 0 4px;
  color: var(--nt-ink-faint);
  font-size: 9.5px;
  text-align: center;
}

/* ── 窄屏 ───────────────────────────────────────────────────────────── */

@media (max-width: 620px) {
  .intro-shell {
    padding: 26px 16px 20px;
  }

  .cover-head {
    align-items: flex-start;
    gap: 12px;
  }

  h1 {
    font-size: clamp(34px, 11vw, 44px);
  }

  .world-note {
    display: none;
  }

  .guide-list li::after {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-delay: 0s !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    transition-delay: 0s !important;
  }
}
